#!/usr/bin/env python3
"""Writes one showcase card per Figma page (components/Screens*/preview.html + README.md) from
project/screens/index.json, plus the Screens brand-book section.

Usage: build_screens.py <output dir>   (run after specs.py)
"""
import json
import sys
from pathlib import Path

ROOT = Path(sys.argv[1]); P = ROOT / 'project'
index = json.loads((P / 'screens/index.json').read_text())

# Figma page slug -> (card folder, title, one-paragraph description)
CARDS = {
    'main-page': ('ScreensMain', 'Main screens',
                  'The two screens the application is built around: Home, and a project open for printing with the Agent pane beside the 3D view. Also the chat list and the full Agent pane for one print.'),
    'printer-material-settings': ('ScreensPrinterAndFilament', 'Printer and filament',
                  'The project screen with each header menu open: choosing a printer, choosing a filament for one slot or several, the filament library, the colour picker, tooltips, and the three steps of adding a printer.'),
    'plates-project-pane': ('ScreensPlatesAndProject', 'Plates and project pane',
                  'The left pane of a project in every state: plates and their objects, folded plate summaries, row menus, and the Project tab with details and print history.'),
    'agent-ui-states-components': ('ScreensAgentPane', 'Agent pane states',
                  'The Agent pane in context and its state matrices: tool and plan approvals, manufacturing history records, recovery notices, connection and command errors, the chat header, chat list, composer and message content, and the printer conversation.'),
    'agent-setup-empty-state': ('ScreensAgentSetup', 'Agent setup',
                  'Connecting an AI model to the Agent pane, one step per screen: the entry card, entering an API key and checking it, finding AI tools on this computer, reviewing the change, and the result.'),
    'current-setup-card': ('ScreensSetupCard', 'Setup card',
                  'The card that summarises the current print setup, in every state: collapsed and expanded, just changed, out of date, edited by hand, while the Agent works, with a risk, and with long or missing content.'),
    'on-boarding-experience': ('ScreensOnboarding', 'Onboarding',
                  'First run from welcome to first print: signing in, email code, browser hand-off, checking the AI connection, finding an existing OrcaSlicer setup, confirming the printer, and the first guided project.'),
    'component-review': ('ScreensReviewComponents', 'Components in review',
                  'Components drawn on the review page of the design file and not yet promoted to the main component page: code block, diff block, notice strip, system line, printer candidate card, network row and the canvas tool strip.'),
}

LEGEND = '''## Reading a spec file

Each screen has a specification file, `screens/<page>/<screen>.spec.txt`: one line per layer, indented by nesting, giving its size, how it sizes (fixed, hug or fill), its layout (direction, alignment, gap, padding), fill, border, radius, shadow, text style and text. Colours, radii and text styles are named by token. A value followed by "(typed in)" is not bound to a token in the design file; prefer the nearest token when you build.

The preview above draws the same layer tree with the tokens (the drawings for a whole page are in `screens/<page>/rendered.json`), so it follows the light and dark themes.

"instance of X (Variant)" on a line names the design-system component to use there. Build with that component rather than copying the layers under it.
'''

used = set()
sections = []
for pg in index:
    if not pg['frames']: continue
    folder, title, blurb = CARDS.get(pg['slug'], ('Screens' + ''.join(w.capitalize() for w in pg['slug'].split('-')), pg['page'], ''))
    used.add(folder)
    frames = pg['frames']
    maxh = max(min(f['h'], 800) for f in frames)
    opts = []
    last = None
    for i, f in enumerate(frames):
        label = (f['set'] + ' / ' if f['set'] else '') + f['name']
        opts.append(f'<option value="{i}">{label.replace("&", "&amp;").replace("<", "&lt;")}</option>')
    data = [{'s': f['slug'], 'w': f['w'], 'h': f['h']} for f in frames]
    preview = f'''<!-- @dsCard group="Screens" height={int(min(maxh, 800) * 0.62) + 80} page=true -->
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>{title}</title>
<style>
  body {{ margin: 0; background: var(--surface-subtle); color: var(--text-primary); font-family: var(--font-sans); }}
  .bar {{ display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-8); padding: var(--space-12) var(--space-16); }}
  .bar label {{ color: var(--text-secondary); }}
  .bar select {{ box-sizing: border-box; max-width: 100%; min-width: 0; height: 26px; padding: 0 var(--space-8); border: 0; border-radius: var(--radius-small); background: var(--surface-canvas); color: var(--text-primary); box-shadow: inset 0 0 0 1px var(--border-subtle); font-family: var(--font-sans); }}
  .bar select:focus-visible {{ outline: 2px solid var(--border-focus); outline-offset: 2px; }}
  .where {{ color: var(--text-secondary); overflow-wrap: anywhere; }}
  .stage {{ padding: 0 var(--space-16) var(--space-16); }}
  .box {{ overflow: hidden; box-shadow: 0 0 0 1px var(--border-subtle); background: var(--surface-canvas); }}
  .fit {{ transform-origin: 0 0; }}
</style>
</head>
<body>
<div class="bar">
  <label class="label" for="frame">Screen</label>
  <select id="frame" class="body-small">{''.join(opts)}</select>
  <span id="where" class="code where"></span>
</div>
<div class="stage"><div id="box" class="box"><div id="fit" class="fit"></div></div></div>
<script>
  var FRAMES = {json.dumps(data, separators=(',', ':'))};
  var BASE = '../../screens/{pg['slug']}/';
  var sel = document.getElementById('frame'), box = document.getElementById('box'), fit = document.getElementById('fit'), where = document.getElementById('where');
  var current = FRAMES[0];
  function size() {{
    var avail = box.parentNode.clientWidth - 32;
    var s = Math.min(1, avail / current.w);
    fit.style.width = current.w + 'px';
    fit.style.transform = 'scale(' + s + ')';
    box.style.width = Math.round(current.w * s) + 'px';
    box.style.height = Math.round(current.h * s) + 'px';
  }}
  var rendered = null;
  function draw() {{ fit.innerHTML = rendered[current.s] || ''; size(); }}
  function show(i) {{
    current = FRAMES[i];
    where.textContent = 'screens/{pg['slug']}/' + current.s + '.spec.txt';
    if (rendered) {{ draw(); return; }}
    fit.textContent = 'Loading\u2026'; size();
    fetch(BASE + 'rendered.json').then(function (r) {{ if (!r.ok) throw new Error(r.status); return r.json(); }})
      .then(function (j) {{ rendered = j; draw(); }})
      .catch(function (e) {{ fit.textContent = 'These screens could not be loaded (' + e.message + ').'; }});
  }}
  sel.addEventListener('change', function () {{ show(Number(sel.value)); }});
  window.addEventListener('resize', size);
  show(0);
</script>
</body>
</html>
'''
    (P / 'components' / folder).mkdir(parents=True, exist_ok=True)
    (P / 'components' / folder / 'preview.html').write_text(preview, encoding='utf-8')
    lines = [f'# {folder}', '', f'{blurb} These are specifications read from the design file layer by layer, not pictures: pick a screen above to see it rendered from the tokens.', '',
             f'Source: the "{pg["page"]}" page of the design file. {len(frames)} screens, {sum(f["layers"] for f in frames):,} layers.', '', '## Screens', '']
    for f in frames:
        label = (f['set'] + ' / ' if f['set'] else '') + f['name']
        lines.append(f'- **{label}** ({f["w"]:g} x {f["h"]:g}): `screens/{pg["slug"]}/{f["slug"]}.spec.txt`')
    if pg['skipped']:
        lines += ['', 'Not included, because the dark appearance comes from the tokens or the design file marks them as not being built: ' + ', '.join(pg['skipped']) + '.']
    notes = [n for n in pg["notes"] if len(n) > 5]
    if notes:
        lines += ['', '## Notes written on the page', ''] + [f'- {n}' for n in notes[:12]]
    lines += ['', LEGEND]
    (P / 'components' / folder / 'README.md').write_text('\n'.join(lines) + '\n', encoding='utf-8')
    sections.append((folder, title, blurb, len(frames), pg['slug']))

    # a local test copy that links the token stylesheet the real preview frame preloads
    local = preview.replace('<head>', '<head><link rel="stylesheet" href="../../../harness/tokens.css">', 1).replace('<html lang="en">', '<html lang="en" data-theme="THEME">')
    for th in ('light', 'dark'):
        (ROOT / 'harness').mkdir(exist_ok=True)
        (ROOT / f'harness/card-{folder}-{th}.html').write_text(local.replace('THEME', th).replace("'../../screens/", "'../project/screens/").replace('../../../harness/tokens.css', 'tokens.css'), encoding='utf-8')

# brand-book section
md = ['# Screens', '',
      'Every screen in the design file, read layer by layer into a specification. Use them to see how the tokens and components come together on a whole screen, and as the reference when building a new one.', '',
      '- Open a group under Components > Screens to see its screens rendered from the tokens, in light or dark.',
      '- Read the matching `.spec.txt` file for exact sizes, spacing, tokens and text. The list of files is in each group\'s guidelines and in `screens/index.json`.',
      '- Where a line says "instance of X", use the design-system component X. Where a value is marked "(typed in)", the design file holds a raw number or colour there; use the nearest token.',
      '- Icons are drawn from their outlines in the design file. Photographs and 3D renders are shown as flat placeholders.', '',
      '| Group | What it covers | Screens |', '|---|---|---:|']
for folder, title, blurb, n, slug in sections:
    md.append(f'| `{folder}` | {blurb.split(":")[0].rstrip(".")}. | {n} |')
(P / 'screens.md').write_text('\n'.join(md) + '\n', encoding='utf-8')
print(len(sections), 'cards:', ', '.join(f'{s[0]} ({s[3]})' for s in sections))

const PAGE_ID = '__PAGE__';
const OFFSET = __OFFSET__;
const CHUNK = 20200;
const page = await figma.getNodeByIdAsync(PAGE_ID);
await figma.setCurrentPageAsync(page);

const varCache = {}, styleCache = {};
const vname = async (id) => {
  if (!(id in varCache)) { let v = null; try { v = await figma.variables.getVariableByIdAsync(id); } catch (e) {} varCache[id] = v ? v.name : '?'; }
  return varCache[id];
};
const sname = async (id) => {
  if (!id || typeof id !== 'string') return '';
  if (!(id in styleCache)) { let s = null; try { s = await figma.getStyleByIdAsync(id); } catch (e) {} styleCache[id] = s ? s.name : '?'; }
  return styleCache[id];
};
const hex = (c) => '#' + [c.r, c.g, c.b].map(v => Math.round(v * 255).toString(16).padStart(2, '0')).join('').toUpperCase();
const R = (v) => Math.round(v * 10) / 10;
const paint = async (arr) => {
  if (!Array.isArray(arr)) return 'mixed';
  const out = [];
  for (const p of arr) {
    if (p.visible === false) continue;
    const op = (p.opacity !== undefined && p.opacity < 0.999) ? '@' + Math.round(p.opacity * 100) : '';
    if (p.type !== 'SOLID') { out.push(p.type + op); continue; }
    const b = p.boundVariables && p.boundVariables.color;
    out.push((b ? '$' + await vname(b.id) : hex(p.color)) + op);
  }
  return out.join(',');
};
const TYPES = { FRAME: 'FR', GROUP: 'GR', COMPONENT: 'CO', COMPONENT_SET: 'CS', INSTANCE: 'IN', TEXT: 'TX', RECTANGLE: 'RE', ELLIPSE: 'EL', VECTOR: 'VE', LINE: 'LI', BOOLEAN_OPERATION: 'BO', STAR: 'ST', POLYGON: 'PO', SECTION: 'SE' };
const SHAPES = { VECTOR: 1, LINE: 1, BOOLEAN_OPERATION: 1, ELLIPSE: 1, RECTANGLE: 1, STAR: 1, POLYGON: 1 };
const clean = (s, n) => String(s).replace(/\n/g, '⏎').replace(/\|/g, '/').slice(0, n);
const box = (n) => { const b = n.absoluteBoundingBox; return b ? [b.x, b.y, b.width, b.height].map(Math.round).join(',') : '?'; };

// one node as text, without its position
const describe = async (n) => {
  let s = clean(n.name, 48) + '|' + (TYPES[n.type] || n.type) + '|' + R(n.width) + 'x' + R(n.height);
  const add = async (fn) => { try { const v = await fn(); if (v) s += '|' + v; } catch (e) { s += '|!'; } };
  await add(() => {
    if (!('layoutMode' in n) || n.layoutMode === 'NONE') return '';
    const bv = n.boundVariables || {};
    const bound = ['itemSpacing', 'paddingLeft', 'paddingRight', 'paddingTop', 'paddingBottom'].some(k => bv[k]);
    return 'L:' + n.layoutMode[0] + ' p' + [n.paddingTop, n.paddingRight, n.paddingBottom, n.paddingLeft].map(R).join(',') + ' g' + R(n.itemSpacing)
      + ' ' + n.primaryAxisAlignItems.slice(0, 3) + '/' + n.counterAxisAlignItems.slice(0, 3)
      + (n.layoutWrap === 'WRAP' ? ' wrap' + R(n.counterAxisSpacing || 0) : '') + (bound ? ' v' : '');
  });
  await add(() => ('layoutSizingHorizontal' in n) ? 'Z:' + n.layoutSizingHorizontal.slice(0, 2) + n.layoutSizingVertical.slice(0, 2) : '');
  await add(() => {
    if (!('cornerRadius' in n)) return '';
    const cr = n.cornerRadius;
    const bound = n.boundVariables && (n.boundVariables.topLeftRadius || n.boundVariables.cornerRadius);
    if (typeof cr === 'symbol') return 'R:' + [n.topLeftRadius, n.topRightRadius, n.bottomRightRadius, n.bottomLeftRadius].map(R).join(',');
    return cr ? 'R:' + R(cr) + (bound ? 'v' : '') : '';
  });
  await add(async () => { if (!('fills' in n)) return ''; const f = await paint(n.fills); return f ? 'F:' + f : ''; });
  await add(async () => {
    if (!('strokes' in n) || !Array.isArray(n.strokes) || !n.strokes.length) return '';
    const w = typeof n.strokeWeight === 'symbol' ? [n.strokeTopWeight, n.strokeRightWeight, n.strokeBottomWeight, n.strokeLeftWeight].map(R).join(',') : R(n.strokeWeight);
    const p = await paint(n.strokes);
    return p ? 'S:' + p + ' ' + w + (n.strokeAlign ? n.strokeAlign[0] : '') + (n.dashPattern && n.dashPattern.length ? ' dash' : '') : '';
  });
  await add(() => ('opacity' in n && n.opacity < 0.999) ? 'O:' + Math.round(n.opacity * 100) : '');
  await add(async () => {
    if (!('effects' in n) || !n.effects.length) return '';
    const st = await sname(n.effectStyleId);
    return 'E:' + (st || n.effects.filter(e => e.visible !== false).map(e => e.type[0] + R(e.radius || 0) + (e.offset ? ',' + R(e.offset.x) + ',' + R(e.offset.y) : '') + (e.color ? ',' + hex(e.color) + '@' + Math.round((e.color.a || 0) * 100) : '')).join(';'));
  });
  await add(() => ('rotation' in n && Math.abs(n.rotation) > 0.5) ? 'rot:' + Math.round(n.rotation) : '');
  await add(() => ('clipsContent' in n && n.clipsContent) ? 'clip' : '');
  if (n.type === 'TEXT') {
    await add(() => 'T:' + clean(n.characters, 320));
    await add(async () => {
      const st = typeof n.textStyleId === 'string' ? await sname(n.textStyleId) : '';
      if (st) return 'Y:' + st;
      const fn = n.fontName, fs = n.fontSize, lh = n.lineHeight;
      return 'Y:raw ' + (typeof fn === 'symbol' ? 'mixed' : fn.family + '/' + fn.style) + ' ' + (typeof fs === 'symbol' ? 'mixed' : fs) + (lh && lh.unit === 'PIXELS' ? '/' + R(lh.value) : '');
    });
    await add(() => 'A:' + n.textAlignHorizontal[0] + n.textAutoResize[0] + (n.textDecoration === 'UNDERLINE' ? 'u' : '') + (n.textTruncation === 'ENDING' ? 't' : ''));
  }
  return s;
};

// hash-consed tree: identical subtrees (ignoring their own position) share one id
const ids = new Map(); let nextId = 1;
const build = async (n, parentAuto, depth) => {
  let text = await describe(n);
  const kids = [];
  let isIcon = false;
  if (n.type === 'INSTANCE') {
    let m = null; try { m = await n.getMainComponentAsync(); } catch (e) {}
    const setName = m ? (m.parent && m.parent.type === 'COMPONENT_SET' ? m.parent.name : '') : '';
    text += '|I:' + (m ? (setName ? setName + ':' : '') + m.name : '?');
    isIcon = setName === 'Icon';
    if (isIcon) {
      try {
        const v = n.findOne(x => x.visible !== false && SHAPES[x.type] && ((Array.isArray(x.strokes) && x.strokes.length) || (Array.isArray(x.fills) && x.fills.length)));
        if (v) text += '|IC:' + ((Array.isArray(v.strokes) && v.strokes.length ? await paint(v.strokes) : '') || await paint(v.fills));
      } catch (e) {}
    }
  }
  if (!isIcon && 'children' in n && depth < 16) {
    const vis = n.children.filter(c => c.visible !== false);
    if (vis.length > 3 && vis.every(c => SHAPES[c.type]) && n.width <= 64 && n.height <= 64) {
      const v = vis[0]; let p = '';
      try { p = (Array.isArray(v.strokes) && v.strokes.length ? 'S:' + await paint(v.strokes) + ' ' + (typeof v.strokeWeight === 'symbol' ? 'mixed' : R(v.strokeWeight)) : 'F:' + await paint(v.fills)); } catch (e) {}
      text += '|glyph ' + vis.length + ' ' + p;
    } else {
      const auto = 'layoutMode' in n && n.layoutMode !== 'NONE';
      for (const c of vis) kids.push(await build(c, auto, depth + 1));
    }
  }
  const abs = parentAuto && n.layoutPositioning === 'ABSOLUTE';
  const pos = (!parentAuto || abs) ? '|P:' + R(n.x) + ',' + R(n.y) + (abs ? 'a' : '') : '';
  const key = text + '\n' + kids.map(k => k.id + k.pos).join(',');
  let id = ids.get(key);
  if (!id) { id = nextId++; ids.set(key, id); }
  let size = 1; for (const k of kids) size += k.size;
  return { id, text, pos, kids, size };
};
const emitted = new Set();
const emit = (node, depth, out) => {
  if (node.size >= 3 && emitted.has(node.id)) { out.push(depth + ' ^' + node.id + node.pos); return; }
  if (node.size >= 3) emitted.add(node.id);
  out.push(depth + ' ' + (node.size >= 3 ? '*' + node.id + ' ' : '') + node.text + node.pos);
  for (const k of node.kids) emit(k, depth + 1, out);
};

const out = [];
let minX = 1e9, minY = 1e9, maxX = -1e9, maxY = -1e9;
for (const c of page.children) { const b = c.absoluteBoundingBox; if (!b) continue; minX = Math.min(minX, b.x); minY = Math.min(minY, b.y); maxX = Math.max(maxX, b.x + b.width); maxY = Math.max(maxY, b.y + b.height); }
out.push('PAGE ' + page.name + '|' + page.id + '|' + [minX, minY, maxX - minX, maxY - minY].map(Math.round).join(','));
const SKIP = /dark|not building|outdated/i;
const visit = async (c, section) => {
  if (c.visible === false) return;
  if (c.type === 'SECTION') { out.push('SECTION ' + clean(c.name, 80) + '|' + c.id + '|' + box(c)); for (const k of c.children) await visit(k, c.name); return; }
  if (c.type === 'TEXT') { out.push('NOTE ' + clean(c.characters, 400) + '|' + box(c)); return; }
  if (c.type === 'COMPONENT_SET' || c.type === 'COMPONENT') {
    const all = c.type === 'COMPONENT_SET' ? c.children.slice() : [c];
    let props = '';
    try { const defs = c.componentPropertyDefinitions; props = Object.keys(defs).map(k => k.replace(/#.*$/, '') + ':' + defs[k].type[0] + '=' + clean(defs[k].defaultValue, 40) + (defs[k].variantOptions ? '[' + defs[k].variantOptions.join(',') + ']' : '')).join(' ; '); } catch (e) {}
    out.push('SET ' + clean(c.name, 80) + '|' + c.id + '|' + box(c) + '|' + all.length + ' variants');
    if (c.description) out.push('D: ' + clean(c.description, 700));
    if (props) out.push('P: ' + props);
    for (const v of all) {
      if (/Appearance=Dark/.test(v.name)) continue;
      out.push('@ ' + clean(v.name, 120) + '|' + v.id + '|' + box(v));
      emit(await build(v, false, 0), 0, out);
    }
    return;
  }
  if (!('children' in c)) return;
  if (SKIP.test(c.name)) { out.push('SKIPPED ' + clean(c.name, 80) + '|' + c.id + '|' + box(c)); return; }
  out.push('@ ' + clean(c.name, 120) + '|' + c.id + '|' + box(c));
  emit(await build(c, false, 0), 0, out);
};
for (const c of page.children) {
  try { await visit(c, ''); } catch (e) { out.push('ERR ' + clean(c.name, 60) + ' ' + String(e && e.message ? e.message : e).slice(0, 160)); }
}

__LZW__
const raw = out.join('\n');
const comp = lzw(raw);
return { total: comp.length, rawLen: raw.length, part: comp.slice(OFFSET, OFFSET + CHUNK) };

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

