#!/usr/bin/env python3
"""Turns the decoded Figma structural reads (figma/spec/<page>.txt) into, per screen:
  - a resolved, readable spec outline (.spec.txt) that names tokens, text styles and components
  - an HTML rendering of the same tree built only from tokens (.html)

Usage: specs.py <repo root> <spec dir> <out dir>
"""
import html
import json
import re
import sys
from pathlib import Path

REPO, SPEC_DIR, OUT = Path(sys.argv[1]), Path(sys.argv[2]), Path(sys.argv[3])

TAGS = ('L:', 'Z:', 'R:', 'F:', 'S:', 'O:', 'E:', 'rot:', 'T:', 'Y:', 'A:', 'I:', 'IC:', 'CP:', 'D:', 'K:', 'glyph ')
TYPE_NAMES = {'FR': 'frame', 'GR': 'group', 'CO': 'component', 'CS': 'component set', 'IN': 'instance', 'TX': 'text', 'RE': 'rectangle',
              'EL': 'ellipse', 'VE': 'vector', 'LI': 'line', 'BO': 'shape', 'ST': 'shape', 'PO': 'shape', 'SE': 'section'}
SHAPES = {'VE', 'LI', 'BO', 'EL', 'RE', 'ST', 'PO'}


class Node:
    __slots__ = ('name', 'type', 'w', 'h', 'f', 'pos', 'absolute', 'kids', 'flags')

    def __init__(self):
        self.kids = []; self.f = {}; self.pos = None; self.absolute = False; self.flags = set()


def parse_text(text):
    """'name|TY|WxH|tag...|P:x,y' -> Node (without children)"""
    n = Node()
    parts = text.split('|')
    m = re.fullmatch(r'P:(-?[\d.]+),(-?[\d.]+)(a?)', parts[-1])
    if m:
        n.pos = (float(m.group(1)), float(m.group(2))); n.absolute = bool(m.group(3)); parts = parts[:-1]
    n.name, n.type = parts[0], parts[1]
    w, h = parts[2].split('x'); n.w, n.h = float(w), float(h)
    for p in parts[3:]:
        if p == 'clip': n.flags.add('clip'); continue
        if p == '!': continue
        for t in TAGS:
            if p.startswith(t):
                n.f[t.rstrip(': ')] = p[len(t):]; break
        else:
            # a '|' inside text was replaced by '/', so anything unknown belongs to the previous text field
            if 'T' in n.f: n.f['T'] += '/' + p
    return n


def clone(n, pos, absolute):
    c = Node(); c.name, c.type, c.w, c.h, c.f, c.kids, c.flags = n.name, n.type, n.w, n.h, n.f, n.kids, n.flags
    c.pos, c.absolute = pos, absolute
    return c


def parse_page(path):
    lines = path.read_text(encoding='utf-8').split('\n')
    page = {'items': [], 'notes': [], 'skipped': []}
    defs = {}; stack = []; cur = None; section = ''
    for ln in lines:
        if ln.startswith('PAGE '):
            name, pid, box = ln[5:].split('|')[:3]; page.update(name=name, id=pid, box=[int(x) for x in box.split(',')]); continue
        if ln.startswith('SECTION '): section = ln[8:].split('|')[0]; continue
        if ln.startswith('NOTE '): page['notes'].append(ln[5:].rsplit('|', 1)[0]); continue
        if ln.startswith('SKIPPED '): page['skipped'].append(ln[8:].split('|')[0]); continue
        if ln.startswith('ERR '): page.setdefault('errors', []).append(ln); continue
        if ln.startswith('SET '):
            name, sid, box, count = ln[4:].split('|')[:4]
            cur_set = {'kind': 'set', 'name': name, 'id': sid, 'desc': '', 'props': '', 'variants': [], 'section': section}
            page['items'].append(cur_set); cur = None; continue
        if ln.startswith('D: ') and page['items'] and page['items'][-1]['kind'] == 'set' and cur is None: page['items'][-1]['desc'] = ln[3:]; continue
        if ln.startswith('P: ') and page['items'] and page['items'][-1]['kind'] == 'set' and cur is None: page['items'][-1]['props'] = ln[3:]; continue
        if ln.startswith('@ '):
            name, fid, box = ln[2:].rsplit('|', 2)
            cur = {'kind': 'frame', 'name': name, 'id': fid, 'box': box, 'root': None, 'section': section}
            if page['items'] and page['items'][-1]['kind'] == 'set' and ln[2:].count('=') and fid and not page['items'][-1].get('closed'):
                page['items'][-1]['variants'].append(cur)
            else:
                if page['items'] and page['items'][-1]['kind'] == 'set': page['items'][-1]['closed'] = True
                page['items'].append(cur)
            stack = []; continue
        m = re.match(r'(\d+) (.*)$', ln)
        if not m or cur is None: continue
        depth, rest = int(m.group(1)), m.group(2)
        mm = re.match(r'\^(\d+)(?:\|P:(-?[\d.]+),(-?[\d.]+)(a?))?$', rest)
        if mm:
            src = defs[int(mm.group(1))]
            node = clone(src, (float(mm.group(2)), float(mm.group(3))) if mm.group(2) else None, bool(mm.group(4)))
        else:
            mm = re.match(r'\*(\d+) (.*)$', rest)
            node = parse_text(mm.group(2) if mm else rest)
            if mm: defs[int(mm.group(1))] = node
        del stack[depth:]
        if depth == 0: cur['root'] = node
        else: stack[depth - 1].kids.append(node)
        stack.append(node)
    return page


# ---------------------------------------------------------------- tokens
TOKENS = json.loads((OUT.parent / 'tokens.json').read_text()) if (OUT.parent / 'tokens.json').exists() else None
COLOR_NAMES = {t['name'] for t in TOKENS['color']['tokens']} if TOKENS else set()
UNKNOWN_VARS = {}
SPACE = {4, 8, 12, 16, 20, 24, 32, 40, 48}
RADIUS = {4: 'radius-small', 8: 'radius-medium', 12: 'radius-large', 10: 'radius-full'}
STYLE_CLASS = {'Page Title': 'page-title', 'Section': 'section', 'Body': 'body', 'Body Bold': 'body-bold', 'Body Small': 'body-small',
               'Body Small Bold': 'body-small-bold', 'Label': 'label', 'Label Bold': 'label-bold', 'Metadata': 'metadata',
               'Metadata Bold': 'metadata-bold', 'Code': 'code'}
LINE_HEIGHT = {'page-title': 30, 'section': 24, 'body': 20, 'body-bold': 20, 'body-small': 18, 'body-small-bold': 18, 'label': 16, 'label-bold': 16, 'metadata': 14, 'metadata-bold': 14, 'code': 16}
ELEVATION = {'Subtle': 'elevation-subtle', 'Medium': 'elevation-medium', 'Strong': 'elevation-strong'}


ROLE_ORDER = {
    'fill': ['surface-canvas', 'surface-subtle', 'surface-selected', 'surface-failure-inverse', 'action-primary', 'action-disabled', 'border-subtle', 'status-success', 'status-danger', 'status-warning', 'neutral-ink'],
    'text': ['text-primary', 'text-secondary', 'text-tertiary', 'action-primary', 'action-disabled-text', 'status-success', 'status-danger', 'status-warning', 'text-on-failure-secondary', 'text-on-failure-tertiary', 'status-danger-on-inverse'],
    'stroke': ['border-subtle', 'border-strong', 'border-on-failure', 'status-danger', 'action-primary', 'text-secondary', 'text-primary'],
}
LIGHT = {}
if TOKENS:
    for t in TOKENS['color']['tokens']:
        LIGHT[t['name']] = (t['value'] if isinstance(t['value'], str) else t['value']['light']).upper()


def equivalent(hexv, role):
    for name in ROLE_ORDER.get(role, []):
        if LIGHT.get(name) == hexv.upper(): return name
    return None


def token_name(v):
    name = v[1:].replace('/', '-')
    if name not in COLOR_NAMES: UNKNOWN_VARS[name] = UNKNOWN_VARS.get(name, 0) + 1
    return name


def paints(s):
    """'$a/b@40,#FFF' -> list of (kind, value, opacity) bottom to top"""
    out = []
    for p in s.split(','):
        op = 100
        m = re.match(r'(.*)@(\d+)$', p)
        if m: p, op = m.group(1), int(m.group(2))
        out.append(('var' if p.startswith('$') else 'hex' if p.startswith('#') else 'other', p, op))
    return out


def css_paint(s, role='fill'):
    ps = [p for p in paints(s) if p[2] > 0]
    if not ps: return None
    kind, v, op = ps[-1]
    if kind == 'hex' and equivalent(v, role): kind, v = 'var', '$' + equivalent(v, role)
    if kind == 'var':
        c = f'var(--{token_name(v)})'
        return c if op == 100 else f'color-mix(in srgb, {c} {op}%, transparent)'
    if kind == 'hex':
        if op == 100: return v
        r, g, b = (int(v[i:i + 2], 16) for i in (1, 3, 5)); return f'rgba({r},{g},{b},{op / 100:g})'
    return 'var(--border-subtle)'  # image or gradient: neutral placeholder


def spec_paint(s, role='fill'):
    out = []
    for kind, v, op in paints(s):
        eq = equivalent(v, role) if kind == 'hex' else None
        t = token_name(v) if kind == 'var' else (v + (f' (typed in; same value as {eq})' if eq else ' (typed in)') if kind == 'hex' else 'image' if v == 'IMAGE' else v.lower())
        out.append(t + (f' at {op}%' if op != 100 else ''))
    return ' over '.join(reversed(out))


def px(v): return f'{v:g}px'


def space(v): return f'var(--space-{int(v)})' if v in SPACE and v == int(v) else px(v)


def sizing(n):
    z = n.f.get('Z', '')
    if len(z) == 4: z = [{'FI': 'fixed', 'HU': 'hug'}[z[:2]], {'FI': 'fixed', 'HU': 'hug'}[z[2:]]]
    elif len(z) == 2: z = [{'X': 'fixed', 'H': 'hug', 'F': 'fill'}[c] for c in z]
    else: z = ['fixed', 'fixed']
    return z


def layout(n):
    m = re.match(r'([HV]) p([\d.,-]+) g(-?[\d.]+) (\w+)/(\w+)(?: wrap([\d.]+))?( v)?$', n.f.get('L', ''))
    if not m: return None
    return {'dir': m.group(1), 'pad': [float(x) for x in m.group(2).split(',')], 'gap': float(m.group(3)), 'main': m.group(4), 'cross': m.group(5),
            'wrap': m.group(6), 'bound': bool(m.group(7))}


# ---------------------------------------------------------------- icons
GLYPHS = {}
for svg in sorted((REPO / 'resources/jusprin/ui/icons').glob('*.svg')):
    GLYPHS[svg.stem] = re.sub(r'\s+', ' ', re.search(r'<svg[^>]*>(.*)</svg>', svg.read_text(), re.S).group(1)).strip()
ALIAS = {'sliders-horizontal': 'sliders', 'layers': 'layers-3', 'grid': 'grid-3x3', 'reset': 'rotate-ccw', 'reset-to-zero': 'undo-dot', 'scale': 'maximize-2', 'duplicate': 'copy', 'more-horizontal': 'ellipsis', 'play-circle': 'circle-play',
         'alert-circle': 'circle-alert', 'check-circle': 'circle-check', 'alert-triangle': 'triangle-alert', 'help-circle': 'info', 'trash': 'x', 'edit': 'pencil',
         'kebab': 'ellipsis', 'gear': 'settings', 'cog': 'settings', 'external-link': 'arrow-up', 'paperclip': 'plus', 'chat-icon': 'chevron-left', 'back': 'chevron-left'}
MISSING_GLYPHS = {}


def only_shapes(n):
    if n.type in SHAPES: return True
    if n.type in ('FR', 'GR', 'IN', 'CO', 'BO') and n.kids: return all(only_shapes(k) for k in n.kids)
    return False


def first_shape(n):
    if n.type in SHAPES: return n
    for k in n.kids:
        s = first_shape(k)
        if s: return s
    return None


def glyph_name(n, parent_name):
    if 'I' in n.f and n.f['I'].startswith('Icon:'): return n.f['I'].split('Type=')[-1]
    for cand in (n.name, parent_name or ''):
        c = cand.lower().strip()
        c = re.sub(r'[-_ ]?(icon|container|glyph)$', '', c)
        c = re.sub(r'^(icon)[-_ /]', '', c)
        if c in GLYPHS or c in ALIAS: return c
    return n.name.lower()


def is_icon(n):
    if 'I' in n.f and n.f['I'].startswith('Icon:'): return True
    return n.type in ('FR', 'GR', 'IN', 'BO') and n.w <= 40 and n.h <= 40 and bool(n.kids) and all(k.type in SHAPES for k in n.kids) and any(k.type in ('VE', 'BO') for k in n.kids)


# ---------------------------------------------------------------- html
def stroke_css(n, styles, shadows):
    s = n.f.get('S')
    if not s: return
    m = re.match(r'(.*) ([\d.,]+|mixed)([IOC]?)( dash)?$', s)
    if not m: return
    color = css_paint(m.group(1), 'stroke')
    if not color: return
    w, align, dash = m.group(2), m.group(3) or 'I', m.group(4)
    if ',' in w:
        t, r, b, l = (float(x) for x in w.split(','))
        if t: shadows.append(f'inset 0 {px(t)} 0 0 {color}')
        if r: shadows.append(f'inset -{px(r)} 0 0 0 {color}')
        if b: shadows.append(f'inset 0 -{px(b)} 0 0 {color}')
        if l: shadows.append(f'inset {px(l)} 0 0 0 {color}')
        return
    w = 1.0 if w == 'mixed' else float(w)
    if dash: styles.append(f'outline:{px(w)} dashed {color};outline-offset:-{px(w)}'); return
    shadows.append((f'0 0 0 {px(w)} {color}') if align == 'O' else f'inset 0 0 0 {px(w)} {color}')


def render(n, parent, depth, parent_name=''):
    """parent: None for the root, else the parent's layout dict or False for a non-auto parent"""
    st = ['box-sizing:border-box', 'flex:none']
    attrs = ''
    lay = layout(n)
    hz, vt = sizing(n)
    rot = int(n.f.get('rot', 0))
    w, h = n.w, n.h

    if parent is None: st.append('position:relative')
    elif parent is False or n.absolute:
        st.append(f'position:absolute;left:{px(n.pos[0] if n.pos else 0)};top:{px(n.pos[1] if n.pos else 0)}')
    elif any(k.absolute or False for k in n.kids) or (not lay and n.kids): st.append('position:relative')
    if parent is not None and lay is None and n.kids and 'position:absolute' not in ';'.join(st) and 'position:relative' not in st: st.append('position:relative')
    if any(k.absolute for k in n.kids) and not any(s.startswith('position') for s in st): st.append('position:relative')

    if 'I' in n.f: attrs += f' data-c="{html.escape(n.f["I"], quote=True)}"'
    if depth <= 2 and n.type != 'TX': attrs += f' data-n="{html.escape(n.name, quote=True)}"'

    # icons
    if is_icon(n):
        g = glyph_name(n, parent_name)
        key = ALIAS.get(g, g)
        shape = first_shape(n)
        color = css_paint(n.f['IC'], 'text') if 'IC' in n.f else None
        if not color and shape is not None:
            sm = re.match(r'(.*) [\d.,]+[IOC]?', shape.f.get('S', ''))
            color = css_paint(sm.group(1), 'text') if sm else (css_paint(shape.f['F'], 'text') if 'F' in shape.f else None)
        st.append(f'width:{px(w)};height:{px(h)}')
        if color: st.append(f'color:{color}')
        if rot: st.append(f'transform:rotate({-rot}deg)')
        drawn = svg_shapes(n, 0, 0, True) if n.kids else ''
        exact = ('I' in n.f) or n.name.lower() in GLYPHS or (g in GLYPHS)
        if key in GLYPHS and (exact or not drawn):
            inner = f'<svg viewBox="0 0 24 24" width="{w:g}" height="{h:g}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="display:block">{GLYPHS[key]}</svg>'
        else:
            if drawn:
                inner = f'<svg viewBox="0 0 {w:g} {h:g}" width="{w:g}" height="{h:g}" fill="none" style="display:block;overflow:visible">{drawn}</svg>'
            else:
                MISSING_GLYPHS[g] = MISSING_GLYPHS.get(g, 0) + 1; inner = ''
        return f'<span{attrs} data-icon="{html.escape(g, quote=True)}" style="{";".join(st)};display:inline-block">{inner}</span>'

    shadows = []
    # size
    if n.type == 'TX':
        a = n.f.get('A', 'LW')
        resize = a[1] if len(a) > 1 else 'W'
        y0 = n.f.get('Y', '')
        lh = LINE_HEIGHT.get(STYLE_CLASS.get(y0, ''), 0)
        if not lh:
            mm = re.search(r'/([\d.]+)$', y0); lh = float(mm.group(1)) if mm else 18
        wrapped = h > lh * 1.4 and '\u23ce' not in n.f.get('T', '')
        if resize == 'W' and hz != 'fill' and not wrapped: st.append('white-space:nowrap')
        elif resize == 'W' and hz != 'fill': st.append(f'width:{px(w)}')
        else:
            if hz == 'fill': st.append('flex:1 1 0;min-width:0' if parent and parent['dir'] == 'H' else 'align-self:stretch')
            else: st.append(f'width:{px(w)}')
            if resize in ('N', 'T'): st.append(f'height:{px(h)};overflow:hidden')
        if 't' in a[2:]: st.append('white-space:nowrap;overflow:hidden;text-overflow:ellipsis')
        if a[0] == 'C': st.append('text-align:center')
        elif a[0] == 'R': st.append('text-align:right')
        if 'u' in a[2:]: st.append('text-decoration:underline')
        c = css_paint(n.f['F'], 'text') if 'F' in n.f else None
        if c: st.append(f'color:{c}')
        y = n.f.get('Y', '')
        cls = STYLE_CLASS.get(y)
        if not cls and y.startswith('raw '):
            m = re.match(r'raw (.*)/(\w[\w ]*) ([\d.]+)(?:/([\d.]+))?$', y) or re.match(r'raw (mixed)()? ?([\d.]+)(?:/([\d.]+))?$', y)
            if m:
                st.append(f'font-size:{m.group(3)}px' + (f';line-height:{m.group(4)}px' if m.group(4) else '') + (';font-weight:700' if 'Bold' in (m.group(2) or '') else ''))
                if 'Mono' in m.group(1): st.append('font-family:var(--font-code)')
        if rot: st.append(f'transform:rotate({-rot}deg)')
        text = html.escape(n.f.get('T', '')).replace('⏎', '<br>')
        return f'<div{attrs}{f" class=\"{cls}\"" if cls else ""} style="{";".join(st)}">{text}</div>'

    if n.type == 'LI':
        m = re.match(r'(.*) ([\d.]+)', n.f.get('S', ''))
        color = css_paint(m.group(1), 'stroke') if m else None
        t = float(m.group(2)) if m else 1
        ww, hh = (t, w) if abs(rot) == 90 else (w, t)
        if parent and parent['dir'] == ('V' if abs(rot) != 90 else 'H') and hz != 'hug' and abs(rot) != 90: st.append('align-self:stretch')
        st.append(f'width:{px(ww)};height:{px(hh)}')
        if color: st.append(f'background:{color}')
        return f'<div{attrs} style="{";".join(st)}"></div>'

    for axis, mode, v in (('width', hz, w), ('height', vt, h)):
        if mode == 'fixed' or n.type in SHAPES or parent is None or parent is False or n.absolute: st.append(f'{axis}:{px(v)}')
        elif mode == 'fill':
            main = parent and ((parent['dir'] == 'H') == (axis == 'width'))
            st.append(('flex:1 1 0;min-' + axis + ':0') if main else 'align-self:stretch')
    if rot and n.type != 'TX': st.append(f'transform:rotate({-rot}deg)')

    if lay:
        st.append('display:flex' + (';flex-direction:column' if lay['dir'] == 'V' else ''))
        if lay['gap'] and lay['main'] != 'SPA': st.append(f'gap:{space(lay["gap"])}')
        if any(lay['pad']): st.append('padding:' + ' '.join(space(v) for v in lay['pad']))
        j = {'MIN': None, 'CEN': 'center', 'MAX': 'flex-end', 'SPA': 'space-between'}[lay['main']]
        if j: st.append(f'justify-content:{j}')
        a = {'MIN': 'flex-start', 'CEN': 'center', 'MAX': 'flex-end', 'BAS': 'baseline'}.get(lay['cross'], 'flex-start')
        st.append(f'align-items:{a}')
        if lay['wrap'] is not None: st.append(f'flex-wrap:wrap;row-gap:{px(float(lay["wrap"]))}')

    if 'F' in n.f:
        c = css_paint(n.f['F'])
        if c: st.append(f'background:{c}')
        if 'IMAGE' in n.f['F']: attrs += ' data-image="placeholder"'
    r = n.f.get('R')
    if n.type == 'EL': st.append('border-radius:50%')
    elif r:
        bound = r.endswith('v'); r = r.rstrip('v')
        vals = [float(x) for x in r.split(',')]
        st.append('border-radius:' + ' '.join((f'var(--{RADIUS[v]})' if bound and v in RADIUS else px(v)) for v in vals))
    stroke_css(n, st, shadows)
    e = n.f.get('E')
    if e:
        name = e.split('/')[-1].split(' ')[0]
        if e.startswith('Elevation/') and name in ELEVATION: shadows.append(f'var(--{ELEVATION[name]})')
        else:
            for part in e.split(';'):
                m = re.match(r'D([\d.]+),(-?[\d.]+),(-?[\d.]+),(#\w+)@(\d+)', part)
                if m:
                    rr, gg, bb = (int(m.group(4)[i:i + 2], 16) for i in (1, 3, 5))
                    shadows.append(f'{m.group(2)}px {m.group(3)}px {m.group(1)}px rgba({rr},{gg},{bb},{int(m.group(5)) / 100:g})')
    if shadows: st.append('box-shadow:' + ','.join(shadows))
    if 'O' in n.f: st.append(f'opacity:{int(n.f["O"]) / 100:g}')
    if 'clip' in n.flags: st.append('overflow:hidden')
    if 'glyph' in n.f: attrs += ' data-glyph="omitted"'

    inner = ''.join(render(k, lay if lay else False, depth + 1, n.name) for k in n.kids)
    return f'<div{attrs} style="{";".join(st)}">{inner}</div>'


def walk(n):
    yield n
    for k in n.kids: yield from walk(k)


def svg_shapes(n, ox, oy, root=False):
    """SVG markup for the shapes under an icon frame, from the outlines read from the design file."""
    out = ''
    for k in ([n] if not root else n.kids):
        x, y = (k.pos if k.pos else (0, 0))
        x += ox; y += oy
        sm = re.match(r'(.*) ([\d.]+)', k.f.get('S', ''))
        sw = sm.group(2) if sm else None
        cap = 'round' if k.f.get('K') == 'R' else 'butt'
        paint = (f'stroke="currentColor" stroke-width="{sw}" stroke-linecap="{cap}" stroke-linejoin="round" fill="none"' if sw else 'fill="currentColor"')
        if 'D' in k.f:
            out += f'<path transform="translate({x:g} {y:g})" d="{html.escape(k.f["D"], quote=True)}" {paint}/>'
        elif k.type == 'EL':
            out += f'<ellipse cx="{x + k.w / 2:g}" cy="{y + k.h / 2:g}" rx="{k.w / 2:g}" ry="{k.h / 2:g}" {paint}/>'
        elif k.type == 'RE':
            r = (k.f.get('R', '0').rstrip('v').split(',')[0])
            out += f'<rect x="{x:g}" y="{y:g}" width="{k.w:g}" height="{k.h:g}" rx="{r}" {paint}/>'
        elif k.type == 'LI' and sw:
            out += f'<line x1="{x:g}" y1="{y:g}" x2="{x + k.w:g}" y2="{y:g}" {paint}/>'
        elif k.kids:
            for c in k.kids: out += svg_shapes(c, x, y)
    return out


# ---------------------------------------------------------------- readable spec
def describe(n, parent, indent, out):
    bits = []
    lay = layout(n)
    hz, vt = sizing(n)
    label = f'"{n.f["T"].replace(chr(0x23ce), " / ")}"' if n.type == 'TX' else n.name
    kind = TYPE_NAMES.get(n.type, n.type)
    if 'I' in n.f: kind = 'instance of ' + n.f['I'].replace(':', ' (', 1) + (')' if ':' in n.f['I'] else '')
    if is_icon(n) and n.type != 'TX':
        g = glyph_name(n, ''); kind = 'icon ' + (g if (g in GLYPHS or 'I' in n.f) else g + ' (outline from the design file)')
