LEGEND = '''# How to read this file
# One line per layer, indented by nesting:  name  [kind]  size | layout | fill | border | radius | shadow
# - Sizes are in px at the design size. "hug" sizes to content; "fill" stretches in its parent.
# - layout "row, start/center, gap 8, padding 12 16" is main-axis/cross-axis alignment of an auto-layout frame.
#   A layer with no layout places its children at the stated "at x,y" positions.
# - Colours are design-token names (surface-canvas, text-primary, ...). "(typed in)" marks a value that is not bound to a token in the design file.
# - Text lines show the text in quotes, then the type style (body, label-bold, ...) and colour token.
# - "instance of X (Variant)" names the design-system component to use; its inner layers follow for reference.
'''


def slug(s):
    s = s.lower().replace('·', '-').replace('+', ' plus ')
    s = re.sub(r'[^a-z0-9]+', '-', s).strip('-')
    return s or 'frame'


def main():
    index = []
    for path in sorted(SPEC_DIR.glob('*.txt')):
        page = parse_page(path)
        pslug = slug(page['name'].split('(')[0])
        seen = {}
        frames = []
        for it in page['items']:
            if it['kind'] == 'frame': frames.append((it, None))
            else:
                for v in it['variants']: frames.append((v, it))
        entries = []; rendered = {}
        for fr, parent_set in frames:
            if fr['root'] is None: continue
            base = slug((parent_set['name'] + ' ' if parent_set else '') + fr['name'].replace('Appearance=Light', '').replace(' · Light', ''))[:56].strip('-')
            seen[base] = seen.get(base, 0) + 1
            fslug = base if seen[base] == 1 else f'{base}-{seen[base]}'
            root = fr['root']
            body = render(root, None, 0)
            out = []
            describe(root, None, 0, out)
            head = f'# {page["name"]} / {(parent_set["name"] + " / ") if parent_set else ""}{fr["name"]}\n# Figma node {fr["id"]}, {root.w:g} x {root.h:g}\n'
            if parent_set and parent_set['desc']: head += '# ' + parent_set['desc'] + '\n'
            d = OUT / pslug; d.mkdir(parents=True, exist_ok=True)
            (d / f'{fslug}.spec.txt').write_text(head + LEGEND + '\n' + '\n'.join(out) + '\n', encoding='utf-8')
            rendered[fslug] = body
            entries.append({'slug': fslug, 'name': fr['name'], 'set': parent_set['name'] if parent_set else None, 'id': fr['id'], 'w': root.w, 'h': root.h,
                            'layers': sum(1 for _ in walk(root)), 'section': fr.get('section', '')})
        if entries: (OUT / pslug / 'rendered.json').write_text(json.dumps(rendered, ensure_ascii=False, separators=(',', ':')), encoding='utf-8')
        index.append({'page': page['name'], 'slug': pslug, 'id': page['id'], 'frames': entries, 'notes': page['notes'], 'skipped': page['skipped'], 'errors': page.get('errors', [])})
        print(f'{page["name"]}: {len(entries)} frames, {sum(e["layers"] for e in entries)} layers, skipped {len(page["skipped"])}')
    (OUT / 'index.json').write_text(json.dumps(index, indent=1, ensure_ascii=False), encoding='utf-8')
    if UNKNOWN_VARS: print('variables not in tokens.json:', UNKNOWN_VARS)
    if MISSING_GLYPHS: print('glyphs with no artwork:', dict(sorted(MISSING_GLYPHS.items(), key=lambda kv: -kv[1])[:40]))


main()

