#!/usr/bin/env python3
"""Builds the "JusPrin v2" Design canvas from the decoded Figma reads: one canvas page per Figma page,
one artboard per top-level Figma frame or component set, at the frame's Figma position.

Usage: build_canvas.py <repo> <out dir>      (reads figma/spec2/*.txt and figma/spec2dark/*.txt beside this script)
"""
import datetime
import html
import json
import re
import sys
from pathlib import Path

SCR = Path(__file__).resolve().parent
REPO, OUT = sys.argv[1], Path(sys.argv[2])
P = OUT / 'project'
DS_URL = 'https://claude.ai/artifact/3zgiix8rAw3rXextQnR5UL'
DS_VERSION = sys.argv[3] if len(sys.argv) > 3 else None

import figlib
S, draw = figlib.load(REPO, SCR / 'jusprin-ds/project/screens')
parse_page, render, slug = S['parse_page'], S['render'], S['slug']


def themed(theme, style, inner):
    return f'<div data-theme="{theme}" class="body" style="{style};color:var(--text-primary);font-family:var(--font-sans)">{inner}</div>'


def artboard(title, w, h, body):
    t = html.escape(title)
    return f'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>{t}</title>
<script src="./support.js"></script>
<link rel="stylesheet" href="ds/jusprin/tokens.css">
</head>
<body>
<x-dc>
<helmet>
<style>
body{{margin:0}}
</style>
</helmet>
{body}
</x-dc>
<script type="text/x-dc" data-dc-script data-props='{{"$preview":{{"width":{w},"height":{h}}}}}'>
class Component extends DCLogic {{
renderVals() {{ return {{}}; }}
}}
</script>
</body>
</html>
'''


def frame_board(fr, theme):
    x, y, w, h = box_of(fr['box'])
    W, H = max(40, w), max(40, h)
    inner = draw(fr['root'], theme)
    center = ';display:flex;align-items:center;justify-content:center' if (W, H) != (w, h) else ''
    body = themed(theme, f'width:{W}px;height:{H}px;position:relative;overflow:hidden;background:var(--surface-canvas){center}', inner)
    return x, y, W, H, body


def set_board(st):
    x, y, w, h = box_of(st['box'])
    vb = [box_of(v['box']) for v in st['variants']]
    def overlap(p, q):
        ix = min(p[0] + p[2], q[0] + q[2]) - max(p[0], q[0]); iy = min(p[1] + p[3], q[1] + q[3]) - max(p[1], q[1])
        return ix > 0 and iy > 0 and ix * iy > 0.25 * min(p[2] * p[3], q[2] * q[3])
    if any(overlap(p, q) for i, p in enumerate(vb) for q in vb[i + 1:]):
        # the design file stacks these variants on top of each other; lay them out in a row so each can be seen
        cx = x + 16
        for i, b in enumerate(vb):
            vb[i] = [cx, y + 16, b[2], b[3]]; cx += b[2] + 16
        w, h = cx - x, max(b[3] for b in vb) + 32
        st['reflowed'] = True
    else:
        # grow the frame to hold variants that stick out of it
        x2, y2 = max([x + w] + [b[0] + b[2] for b in vb]), max([y + h] + [b[1] + b[3] for b in vb])
        x, y = min([x] + [b[0] for b in vb]), min([y] + [b[1] for b in vb]); w, h = x2 - x, y2 - y
    W, H = max(40, w), max(40, h)
    parts = []
    dk = [b for v, b in zip(st['variants'], vb) if v['theme'] == 'dark']
    lt = [b for v, b in zip(st['variants'], vb) if v['theme'] != 'dark']
    panel = False
    if dk and st['theme'] != 'dark':
        dx, dy = min(b[0] for b in dk) - 8, min(b[1] for b in dk) - 8
        dx2, dy2 = max(b[0] + b[2] for b in dk) + 8, max(b[1] + b[3] for b in dk) + 8
        if not any(b[0] < dx2 and b[0] + b[2] > dx and b[1] < dy2 and b[1] + b[3] > dy for b in lt):
            panel = True
            parts.append(f'<div data-theme="dark" style="position:absolute;left:{dx - x + (W - w) / 2:g}px;top:{dy - y + (H - h) / 2:g}px;width:{dx2 - dx}px;height:{dy2 - dy}px;border-radius:var(--radius-small);background:var(--surface-canvas)"></div>')
    for v, (vx, vy, vw, vh) in zip(st['variants'], vb):
        th = v['theme']
        left, top = vx - x + (W - w) / 2, vy - y + (H - h) / 2
        if th == 'dark' and st['theme'] != 'dark' and not panel:
            parts.append(f'<div data-theme="dark" style="position:absolute;left:{left - 8:g}px;top:{top - 8:g}px;width:{vw + 16}px;height:{vh + 16}px;border-radius:var(--radius-small);background:var(--surface-canvas)"></div>')
        parts.append(f'<div data-theme="{th}" title="{html.escape(v["name"], quote=True)}" style="position:absolute;left:{left:g}px;top:{top:g}px;color:var(--text-primary)">{draw(v["root"], th)}</div>')
    body = themed(st['theme'], f'width:{W}px;height:{H}px;position:relative;background:var(--surface-canvas);outline:1px dashed var(--border-strong);outline-offset:-1px;border-radius:var(--radius-small)', ''.join(parts))
    return x, y, W, H, body


def load(pid, sub):
    f = SCR / 'figma' / sub / (pid.replace(':', '-') + '.txt')
    return (parse_page(f), f.read_text(encoding='utf-8').split('\n')) if f.exists() else (None, [])


boards, order, notes, pages, files = {}, [], {}, [], {}
REFLOWED = []
stats = []
note_n = 0


def add_note(page, **kw):
    global note_n
    note_n += 1
    notes[f'n{note_n}'] = dict(kw, page=page)


for pid, pname, cpage, prefix in PAGES:
    pages.append({'id': cpage, 'name': pname})
    light, lines = load(pid, 'spec2')
    if light is None:
        add_note(cpage, x=0, y=0, w=420, text='The design file marks this page as obsolete, so its frames were not brought over.')
        stats.append((pname, 0, 0, 0)); continue
    dark, dark_lines = load(pid, 'spec2dark')
    items = []
    by_id = {}
    for it in light['items']:
        if it['kind'] == 'set':
            if not it['variants']: continue
            it['theme'] = 'dark' if is_dark(it['name']) else 'light'
            for v in it['variants']: v['theme'] = 'dark' if (it['theme'] == 'dark' or 'Appearance=Dark' in v['name']) else 'light'
            by_id[it['id']] = it
        else:
            if it['root'] is None: continue
            it['theme'] = 'dark' if is_dark(it['name']) else 'light'
        items.append(it)
    n_dark = 0
    if dark:
        for it in dark['items']:
            if it['kind'] == 'set':
                tgt = by_id.get(it['id'])
                for v in it['variants']:
                    v['theme'] = 'dark'
                    if tgt: tgt['variants'].append(v); n_dark += 1
            elif it['root'] is not None:
                it['theme'] = 'dark'; items.append(it); n_dark += 1
    seen = {}
    n_frames = n_sets = 0
    for it in items:
        if it['kind'] == 'set':
            x, y, w, h, body = set_board(it); n_sets += 1
            if it.get('reflowed'): REFLOWED.append(it['name'])
        else:
            x, y, w, h, body = frame_board(it, it['theme']); n_frames += 1
        assert w <= 8000 and h <= 8000, (it['name'], w, h)
        base = slug(it['name'])[:60].strip('-')
        seen[base] = seen.get(base, 0) + 1
        name = f'{prefix}-{base}' + ('' if seen[base] == 1 else f'-{seen[base]}') + '.dc.html'
        if not order: name = 'Main.dc.html'
        assert name not in boards and re.fullmatch(r'[A-Za-z0-9_][A-Za-z0-9_.-]*\.dc\.html', name), name
        boards[name] = {'x': x, 'y': y, 'w': w, 'h': h, 'title': it['name'], 'page': cpage}
        order.append(name)
        files[name] = artboard(it['name'], w, h, body)
    # Figma's own labels on the page: section names and loose text
    for ln in lines:
        if ln.startswith('SECTION '):
            name, sid, box = ln[8:].rsplit('|', 2)
            x, y, w, h = box_of(box)
            if re.search(r'light\s*&\s*dark', name, re.I): add_note(cpage, x=x + 16, y=y + 24, text=name, kind='title1', size=24, maxW=max(240, w - 32))
            else: add_note(cpage, x=x, y=y - 72, text=name, kind='title1', size=40, maxW=max(320, w))
        elif ln.startswith('NOTE '):
            text, box = ln[5:].rsplit('|', 1)
            x, y, w, h = box_of(box)
            text = text.replace('⏎', '\n')
            if '\n' not in text and len(text) <= 60: add_note(cpage, x=x, y=y, text=text, kind='title1', size=max(12, min(72, round(h * 0.8))), maxW=max(240, w + 40))
            else: add_note(cpage, x=x, y=y, w=max(280, w), text=text)
    stats.append((pname, n_frames, n_sets, n_dark))

now = datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
canvas = {
    'v': 3, 'createdOnFiles': {'v': 1, 'at': now}, 'title': 'JusPrin v2',
    'launch': {'view': 'canvas', 'page': PAGES[0][2]},
    'pages': pages, 'boards': boards, 'order': order, 'notes': notes,
    'designSystems': [{'title': 'JusPrin Design System', 'namespace': 'jusprin', 'artifact': DS_URL, 'version': DS_VERSION, 'copiedAt': now}],
}
P.mkdir(parents=True, exist_ok=True)
for old in P.glob('*.dc.html'): old.unlink()
(P / 'canvas.json').write_text(json.dumps(canvas, ensure_ascii=False, indent=1), encoding='utf-8')
for name, text in files.items():
    assert '{{' not in text.split('<x-dc>')[1].split('</x-dc>')[0], name
    (P / name).write_text(text, encoding='utf-8')
total = sum(len(t.encode()) for t in files.values())
for s in stats: print('%-40s frames %3d  sets %3d  dark %3d' % s)
print('reflowed sets:', REFLOWED)
print(len(files), 'artboards,', len(notes), 'notes,', total // 1024, 'KB; largest', max(len(t.encode()) for t in files.values()) // 1024, 'KB')
if S['UNKNOWN_VARS']: print('variables not in tokens.json:', S['UNKNOWN_VARS'])

