            found=None
            for f,_ in fam:
                for x in t[f]['tokens']:
                    if x['name']==n or x['name']==n.replace('spacing-','space-') : found=(f,x)
            if not found: bad.append(('number not matched by name',c['name'],name,vv)); continue
