import figlib
S, draw = figlib.load(REPO, P / 'screens')
parse_page, render, slug = S['parse_page'], S['render'], S['slug']


light = parse_page(figlib.FIGMA / 'spec2/9-153.txt')
dark = parse_page(figlib.FIGMA / 'spec2dark/9-153.txt')
sets = {it['id']: it for it in light['items'] if it['kind'] == 'set'}
singles = {it['id']: it for it in light['items'] if it['kind'] == 'frame' and it['root'] is not None}
dark_sets = {it['id']: it for it in dark['items'] if it['kind'] == 'set'}
by_name = {it['name']: it for it in light['items'] if it['kind'] == 'set'}

# Figma's own prefixes, then the heading Figma gives the cards, then the rest
GROUPS = {'Button': 'Button', 'Field': 'Field', 'Menu': 'Menu', 'Chat': 'Chat'}
CARDS = {'Pinned Setup Card', 'ProjectCard', 'PrinterCard'}

report = []
for comp, node in comps.items():
    prev = P / 'components' / comp / 'preview.html'
    keep = SCR / 'previews_orig' / f'{comp}.html'
    if not keep.exists():
        keep.parent.mkdir(exist_ok=True); keep.write_text(prev.read_text())
    old = keep.read_text()
    script = re.search(r'<script>\n(.*?)</script>', old, re.S).group(1)
    old_h = int(re.search(r'height=(\d+)', old).group(1))
    if node in sets and sets[node]['variants']:
        st = sets[node]; figma = st['name']; variants = st['variants']
        dk = {v['name']: v for v in dark_sets.get(node, {'variants': []})['variants']}
        twin = by_name.get(figma + ' · Dark')
        if twin: dk.update({v['name']: v for v in twin['variants']})
    else:
        fr = singles[node]; figma = fr['name']; variants = [fr]; dk = {}
    tiles = {'light': [], 'dark': []}
    sizes = []
    n_drawn_dark = 0
    for v in variants:
        name = label(v['name'])
        d = dk.get(v['name'].replace('Appearance=Light', 'Appearance=Dark')) if 'Appearance=Light' in v['name'] else dk.get(v['name'])
        if d is not None: n_drawn_dark += 1
        for th, node_ in (('light', v['root']), ('dark', (d or v)['root'])):
            tiles[th].append(f'<figure class="fv-tile"><div>{draw(node_, th)}</div><figcaption class="metadata">{html.escape(name)}</figcaption></figure>')
        sizes.append((max(v['root'].w, len(name) * 5.4), v['root'].h))
    maxw = max(w for w, _ in sizes)
    stacked = maxw > 520
    width = max(1200, int(maxw) + 96) if stacked else 1200

