cat > grads.js <<'EOF'
const IDS = __IDS__;
const hex = (c, a) => '#' + [c.r, c.g, c.b].map(x => Math.round(x * 255).toString(16).padStart(2, '0')).join('').toUpperCase() + ((a !== undefined && a < 0.999) ? Math.round(a * 255).toString(16).padStart(2, '0').toUpperCase() : '');
const out = {};
for (const id of IDS) {
  const n = await figma.getNodeByIdAsync(id);
  if (!n || !Array.isArray(n.fills)) { out[id] = null; continue; }
  const fills = [];
  for (const p of n.fills) {
    if (p.visible === false) continue;
    if (p.type === 'SOLID') { fills.push({ t: 'S', c: hex(p.color, p.opacity) }); continue; }
    if (!p.gradientStops) { fills.push({ t: p.type }); continue; }
    const stops = [];
    for (const s of p.gradientStops) {
      let v = '';
      try { const b = s.boundVariables && s.boundVariables.color; if (b) { const vv = await figma.variables.getVariableByIdAsync(b.id); v = vv ? vv.name : ''; } } catch (e) {}
      stops.push([Math.round(s.position * 10000) / 10000, hex(s.color, s.color.a), v]);
    }
    fills.push({ t: p.type, m: p.gradientTransform, o: p.opacity === undefined ? 1 : p.opacity, s: stops });
  }
  out[id] = { name: n.name, w: n.width, h: n.height, fills };
}
return JSON.stringify(out);
EOF
