  const walk = (n, d) => {
    for (const c of n.children) {
      if (c.type === 'SECTION') { out.push(' '.repeat(d) + 'S ' + c.name + '|' + c.id); walk(c, d + 1); }
      else if ('children' in c || c.type === 'TEXT') out.push(' '.repeat(d) + (c.type === 'TEXT' ? 'T ' + c.characters.slice(0, 60).replace(/\n/g, ' ') : c.type[0] + ' ' + c.name) + '|' + c.id);
    }
  };
  walk(p, 1);
}
return out.join('\n');

