const page = await figma.getNodeByIdAsync('0:1');
await figma.setCurrentPageAsync(page);
const ids = ['68:42', '553:86', '1046:318', '1073:368', '1073:512'];
const removed = [], mutated = [], report = [];
for (const id of ids) {
  const f = await figma.getNodeByIdAsync(id);
  const before = Math.round(f.height);
  for (const av of f.findAll(n => n.name === 'Assistant avatar')) { removed.push(av.id); av.remove(); }
  const ind = f.findAll(n => (n.name === 'Summary alignment' || n.name === 'Adhesion settings') && 'paddingLeft' in n);
  for (const n of ind) {
    if (n.boundVariables && n.boundVariables.paddingLeft) n.setBoundVariable('paddingLeft', null);
    n.paddingLeft = 0;
    const card = n.children[0];
    card.layoutSizingHorizontal = 'FILL';
    mutated.push(n.id, card.id);
  }
  report.push({ id, name: f.name, heightBefore: before, heightAfter: Math.round(f.height), avatarsLeft: f.findAll(n => n.name === 'Assistant avatar').length,
    cards: ind.map(n => n.name + ' pad ' + n.paddingLeft + ' card ' + Math.round(n.children[0].width)) });
}
return { removedNodeIds: removed, mutatedNodeIds: mutated, report };

