const page = await figma.getNodeByIdAsync('1423:396');
await figma.setCurrentPageAsync(page);
await figma.loadFontAsync({ family: 'HarmonyOS Sans SC', style: 'Bold' });
const ids = ['1424:396', '1731:7184', '1452:248', '1471:282', '1471:5968', '1483:344', '1487:498'];
const labelStyle = (await figma.getLocalTextStylesAsync()).find(s => s.name === 'Label Bold');
const created = [], report = [];
for (const id of ids) {
  const f = await figma.getNodeByIdAsync(id);
  if (f.findOne(n => n.name === 'Out of date overlay')) { report.push({ id, skipped: 'already marked' }); continue; }
  const ov = figma.createRectangle();
  ov.name = 'Out of date overlay';
  ov.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 }, opacity: 0.5 }];
  f.appendChild(ov);
  if (f.layoutMode && f.layoutMode !== 'NONE') ov.layoutPositioning = 'ABSOLUTE';
  ov.x = 0; ov.y = 0; ov.resize(f.width, f.height);
  ov.constraints = { horizontal: 'STRETCH', vertical: 'STRETCH' };
  const tag = figma.createAutoLayout('HORIZONTAL', { name: 'Out of date label' });
  tag.paddingLeft = 10; tag.paddingRight = 10; tag.paddingTop = 6; tag.paddingBottom = 6; tag.cornerRadius = 4;
  tag.fills = [{ type: 'SOLID', color: { r: 0x17 / 255, g: 0x13 / 255, b: 0x1f / 255 } }];
  const t = figma.createText();
  t.fontName = { family: 'HarmonyOS Sans SC', style: 'Bold' };
  t.characters = 'Out of date: the Agent no longer asks for approval';
  if (labelStyle) await t.setTextStyleIdAsync(labelStyle.id);
  t.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
  tag.appendChild(t);
  f.appendChild(tag);
  if (f.layoutMode && f.layoutMode !== 'NONE') tag.layoutPositioning = 'ABSOLUTE';
  tag.x = 12; tag.y = 12;
  created.push(ov.id, tag.id, t.id);
  report.push({ id, name: f.name, frame: Math.round(f.width) + 'x' + Math.round(f.height), overlay: Math.round(ov.width) + 'x' + Math.round(ov.height), lastChild: f.children[f.children.length - 1].name });
}
return { createdNodeIds: created, report };

