const page = await figma.getNodeByIdAsync('1423:396');
await figma.setCurrentPageAsync(page);
await figma.loadFontAsync({ family: 'HarmonyOS Sans SC', style: 'Bold' });
await figma.loadFontAsync({ family: 'HarmonyOS Sans SC', style: 'Regular' });
const styles = Object.fromEntries((await figma.getLocalTextStylesAsync()).map(s => [s.name, s]));
const ids = ['1424:396', '1731:7184', '1452:248', '1471:282', '1471:5968', '1483:344', '1487:498'];
const ink = { r: 0x17 / 255, g: 0x13 / 255, b: 0x1f / 255 };
const white = { r: 1, g: 1, b: 1 };
const soft = { r: 0xC8 / 255, g: 0xC1 / 255, b: 0xD2 / 255 };
const removed = [], created = [], report = [];
const text = async (chars, style, color, parent) => {
  const t = figma.createText();
  t.fontName = { family: 'HarmonyOS Sans SC', style: style.fontName.style };
  t.characters = chars;
  await t.setTextStyleIdAsync(style.id);
  t.fills = [{ type: 'SOLID', color }];
  parent.appendChild(t);
  t.textAutoResize = 'HEIGHT';
  t.layoutSizingHorizontal = 'FILL';
  return t;
};
for (const id of ids) {
  const f = await figma.getNodeByIdAsync(id);
  for (const old of f.findAll(n => n.name === 'Out of date label' || n.name === 'Out of date note')) { removed.push(old.id); old.remove(); }
  const w = Math.min(380, f.width - 48);
  const card = figma.createAutoLayout('VERTICAL', { name: 'Out of date note', itemSpacing: 10 });
  card.paddingLeft = card.paddingRight = 20; card.paddingTop = card.paddingBottom = 18;
  card.cornerRadius = 12;
  card.fills = [{ type: 'SOLID', color: ink }];
  card.effects = [{ type: 'DROP_SHADOW', color: { r: 0, g: 0, b: 0, a: 0.16 }, offset: { x: 0, y: 8 }, radius: 24, spread: 0, visible: true, blendMode: 'NORMAL' }];
  // heading row: a no-entry symbol (circle with a bar) and the words "Out of date"
  const row = figma.createAutoLayout('HORIZONTAL', { name: 'Heading', itemSpacing: 10, counterAxisAlignItems: 'CENTER' });
  row.fills = [];
  const sym = figma.createFrame();
  sym.name = 'No-entry symbol'; sym.resize(24, 24); sym.fills = [];
  const ring = figma.createEllipse(); ring.resize(22, 22); ring.x = 1; ring.y = 1;
  ring.fills = []; ring.strokes = [{ type: 'SOLID', color: white }]; ring.strokeWeight = 2.5; ring.strokeAlign = 'INSIDE';
  const bar = figma.createVector();
  bar.vectorPaths = [{ windingRule: 'NONE', data: 'M 0 0 L 14 14' }];
  bar.x = 5; bar.y = 5; bar.strokes = [{ type: 'SOLID', color: white }]; bar.strokeWeight = 2.5; bar.strokeCap = 'ROUND'; bar.fills = [];
  sym.appendChild(ring); sym.appendChild(bar);
  row.appendChild(sym);
  card.appendChild(row);
  row.layoutSizingHorizontal = 'FILL';
  const title = figma.createText();
  title.fontName = { family: 'HarmonyOS Sans SC', style: 'Bold' };
  title.characters = 'Out of date';
  await title.setTextStyleIdAsync(styles['Page Title'].id);
  title.fills = [{ type: 'SOLID', color: white }];
  row.appendChild(title);
  await text('The Agent no longer asks for approval before it acts. It makes the change right away, and you undo it with “Revert to here”.', styles['Body'], white, card);
  await text('Current design: “print-timeline-panel-full” on Main Page.', styles['Label'], soft, card);
  f.appendChild(card);
  if (f.layoutMode && f.layoutMode !== 'NONE') card.layoutPositioning = 'ABSOLUTE';
  card.resize(w, card.height);
  card.layoutSizingHorizontal = 'FIXED'; card.layoutSizingVertical = 'HUG';
  card.x = Math.round((f.width - w) / 2);
  card.y = Math.round(Math.min(f.height / 2, 520) - card.height / 2);
  card.constraints = { horizontal: 'CENTER', vertical: 'MIN' };
  created.push(card.id);
  report.push({ id, name: f.name, note: Math.round(card.width) + 'x' + Math.round(card.height) + ' at ' + card.x + ',' + card.y, overlayKept: !!f.findOne(n => n.name === 'Out of date overlay'), topLayer: f.children[f.children.length - 1].name });
}
return { removedNodeIds: removed, createdNodeIds: created, report };

