const page = await figma.getNodeByIdAsync('9:153');
await figma.setCurrentPageAsync(page);
const version = await figma.saveVersionHistoryAsync('Before Composer redesign', 'Composer component rebuilt to the approved composer-redesign proposal');
await figma.loadFontAsync({ family: 'HarmonyOS Sans SC', style: 'Regular' });
await figma.loadFontAsync({ family: 'HarmonyOS Sans SC', style: 'Bold' });
const V = async (id) => figma.variables.getVariableByIdAsync(id);
const C = { text: await V('VariableID:9:83'), disabledText: await V('VariableID:835:1261') };
const S4 = await V('VariableID:9:31'), S8 = await V('VariableID:9:32');
const RS = await V('VariableID:9:41'), RM = await V('VariableID:9:42');
const TS = Object.fromEntries((await figma.getLocalTextStylesAsync()).map(s => [s.name, s]));
const solid = (v) => figma.variables.setBoundVariableForPaint({ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }, 'color', v);
const radius = (n, v) => { for (const k of ['topLeftRadius', 'topRightRadius', 'bottomLeftRadius', 'bottomRightRadius']) n.setBoundVariable(k, v); };
const pad = (n, v) => { for (const k of ['paddingTop', 'paddingRight', 'paddingBottom', 'paddingLeft']) n.setBoundVariable(k, v); };
const iconSet = await figma.getNodeByIdAsync('591:159');
const iconBtnSet = await figma.getNodeByIdAsync('9:145');
const set = await figma.getNodeByIdAsync('1197:5155');
const defs = set.componentPropertyDefinitions;
const findKey = (name) => Object.keys(defs).find(k => k.split('#')[0] === name);
const modelKey = findKey('Model') || set.addComponentProperty('Model', 'TEXT', 'Claude Opus 5.5');
const levelKey = findKey('Thinking level') || set.addComponentProperty('Thinking level', 'TEXT', 'Thinking: Medium');
const levelsKey = findKey('Thinking levels') || set.addComponentProperty('Thinking levels', 'BOOLEAN', true);
const report = [];
for (const v of set.children) {
  const name = v.name;
  const state = /State=([^,]+)/.exec(name)[1];
  const photo = /Mode=Photo/.test(name);
  const off = state === 'Streaming' || state === 'Unavailable';
  const entry = v.findOne(n => n.name === 'Entry row');
  const input = entry.findOne(n => n.type === 'TEXT' && n.name === 'Input text');
  const action = entry.findOne(n => n.type === 'INSTANCE' && n.name === 'Attachment action');
  const btn = entry.children.filter(n => n.type === 'INSTANCE' && n !== action).pop();
  const attach = v.findOne(n => n.type === 'INSTANCE' && n.name === 'Chat/Attachment');
  // the box
  entry.layoutMode = 'VERTICAL';
  entry.primaryAxisAlignItems = 'MIN'; entry.counterAxisAlignItems = 'MIN';
  entry.setBoundVariable('itemSpacing', S4); pad(entry, S8); radius(entry, RM);
  entry.layoutSizingHorizontal = 'FILL'; entry.layoutSizingVertical = 'HUG';
  // staged attachments sit inside the box, above the text
  if (attach) {
    const list = figma.createAutoLayout('VERTICAL', { name: 'Staged attachments', itemSpacing: 6 });
    list.fills = [];
    entry.insertChild(0, list); list.layoutSizingHorizontal = 'FILL';
    list.appendChild(attach); attach.layoutSizingHorizontal = 'FILL';
  }
  // the growing text area
  const area = figma.createAutoLayout('VERTICAL', { name: 'Input', itemSpacing: 0 });
  area.fills = []; pad(area, S4);
  entry.insertChild(attach ? 1 : 0, area); area.layoutSizingHorizontal = 'FILL';
  area.appendChild(input); input.layoutSizingHorizontal = 'FILL'; input.textAutoResize = 'HEIGHT';
  // toolbar: attach, pickers, then Send or Stop
  const bar = figma.createAutoLayout('HORIZONTAL', { name: 'Toolbar', itemSpacing: 8, counterAxisAlignItems: 'CENTER', primaryAxisAlignItems: 'SPACE_BETWEEN' });
  bar.fills = [];
  entry.appendChild(bar); bar.layoutSizingHorizontal = 'FILL';
  const choices = figma.createAutoLayout('HORIZONTAL', { name: 'Choices', itemSpacing: 4, counterAxisAlignItems: 'CENTER' });
  choices.fills = [];
  bar.appendChild(choices);
  if (photo) {
    choices.appendChild(action);
  } else {
    const plus = iconBtnSet.children.find(c => c.name === 'State=' + (off ? 'Disabled' : 'Default')).createInstance();
    choices.appendChild(plus); plus.name = 'Attach';
    plus.findOne(n => n.type === 'INSTANCE').swapComponent(iconSet.children.find(c => c.name === 'Type=plus'));
    action.remove();
    for (const [label, key, vis] of [['Model', modelKey, null], ['Thinking level', levelKey, levelsKey]]) {
      const p = figma.createAutoLayout('HORIZONTAL', { name: 'Picker · ' + label, itemSpacing: 4, counterAxisAlignItems: 'CENTER' });
      p.fills = [];
      p.setBoundVariable('paddingTop', S4); p.setBoundVariable('paddingBottom', S4); p.setBoundVariable('paddingLeft', S8); p.setBoundVariable('paddingRight', S8); radius(p, RS);
      choices.appendChild(p);
      const t = figma.createText();
      t.fontName = { family: 'HarmonyOS Sans SC', style: 'Regular' };
      t.characters = label === 'Model' ? 'Claude Opus 5.5' : 'Thinking: Medium';
      await t.setTextStyleIdAsync(TS['Label'].id);
      t.fills = [solid(off ? C.disabledText : C.text)];
      t.name = 'label';
      p.appendChild(t);
      t.componentPropertyReferences = { characters: key };
      const ch = iconSet.children.find(c => c.name === 'Type=chevron-down').createInstance();
      ch.name = 'chevron'; p.appendChild(ch);
      if (off) for (const vec of ch.findAll(n => n.type === 'VECTOR')) vec.strokes = [solid(C.disabledText)];
      if (vis) p.componentPropertyReferences = { visible: vis };
    }
  }
  bar.appendChild(btn);
  // the variant matches the Agent pane's message box width
  v.resize(397, v.height); v.primaryAxisSizingMode = 'AUTO';
  const inner = v.findOne(n => n.name === 'Instance');
  if (inner) { inner.layoutSizingHorizontal = 'FILL'; }
  report.push(name.replace(', Focus=Normal', '') + ' -> ' + Math.round(v.width) + 'x' + Math.round(v.height));
}
return { version: version && version.id, properties: Object.keys(set.componentPropertyDefinitions), mutatedNodeIds: set.children.map(v => v.id), report };

