const page = await figma.getNodeByIdAsync('9:153');
await figma.setCurrentPageAsync(page);
const set = await figma.getNodeByIdAsync('1197:5155');
const states = ['Idle', 'Text ready', 'Attachment ready', 'Streaming', 'Unavailable'];
const cols = [['Light', 'Regular'], ['Light', 'Photo'], ['Dark', 'Regular'], ['Dark', 'Photo']];
const W = 397, GX = 24, GY = 16, P = 16;
const rowsOf = (focus) => states.map(s => ({ s, focus }));
const rows = [...rowsOf('Normal'), { s: 'Idle', focus: 'Keyboard focus' }];
let y = P; const placed = [];
for (const r of rows) {
  let h = 0;
  cols.forEach(([ap, mode], ci) => {
    const v = set.children.find(c => c.name === `State=${r.s}, Mode=${mode}, Appearance=${ap}, Focus=${r.focus}`);
    if (!v) return;
    v.x = P + ci * (W + GX); v.y = y; h = Math.max(h, v.height); placed.push(v.id);
  });
  if (h) y += h + GY;
}
const missing = set.children.filter(c => !placed.includes(c.id)).map(c => c.name);
set.resizeWithoutConstraints(P * 2 + 4 * W + 3 * GX, y - GY + P);
const b = set.absoluteBoundingBox;
const hits = page.children.filter(n => n.id !== set.id && n.absoluteBoundingBox).filter(n => { const o = n.absoluteBoundingBox; return o.x < b.x + b.width && o.x + o.width > b.x && o.y < b.y + b.height && o.y + o.height > b.y; }).map(n => n.name + ' ' + n.id);
return { mutatedNodeIds: [set.id, ...placed], setBox: [Math.round(b.x), Math.round(b.y), Math.round(b.width), Math.round(b.height)], missing, overlapsWith: hits };

