import json,re
code=json.load(open('resources/jusprin/ui/design-tokens.json'))
ds=json.load(open('/Users/kenneth/.claude/projects/-Users-kenneth-Projects-JusPrin/figma-mirror/published/ds/project/tokens.json'))
norm=lambda s: re.sub(r'[^a-z0-9]','',s.lower())
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items(): yield from walk(v,p+'/'+k if p else k)
    else: yield p,o
cl={norm(k[len('semantic/light/'):]):(k,v) for k,v in walk(code) if k.startswith('semantic/light/')}
cd={norm(k[len('semantic/dark/'):]):(k,v) for k,v in walk(code) if k.startswith('semantic/dark/')}
alias={'actiononprimary':'actionprimarytext','statusdangeroninverse':'statusdangeroninverse','surfacefailureinverse':'surfacefailureinverse'}
print('== colours: DS (Figma) vs code')
for t in ds['color']['tokens']:
    n=norm(t['name']); n2=alias.get(n,n)
    v=t['value']; l,d=(v,v) if isinstance(v,str) else (v['light'],v['dark'])
    if t['name'].startswith(('brand-','neutral-')): continue
    a=cl.get(n2); b=cd.get(n2)
    if not a: print('  not in code:',t['name'],l,d); continue
    if a[1].upper()!=l.upper() or (b and b[1].upper()!=d.upper()): print('  differs:',t['name'],'figma',l,d,'| code',a[0],a[1],b[1] if b else None)
dsn={alias.get(norm(t['name']),norm(t['name'])) for t in ds['color']['tokens']}
print('  in code only:',sorted(k for k in cl if k not in dsn))
print('== radius', [(t['name'],t['value']) for t in ds['radius']['tokens']], '| code', {k:v for k,v in walk(code) if k.startswith('dimension/radius')})
print('== spacing same?', [t['value'] for t in ds['spacing']['tokens']], '| code', [v for k,v in walk(code) if k.startswith('dimension/space')])
print('== shadows', [(t['name'],t['value']) for t in ds['shadow']['tokens']])
print('   code', {k:v for k,v in walk(code) if k.startswith('elevation')})
print('== type code', {k:v for k,v in walk(code) if k.startswith('typography/ui') or k.startswith('typography/code')})
EOF

