const page = await figma.getNodeByIdAsync('1423:396');
await figma.setCurrentPageAsync(page);
const leftovers = page.children.filter(n => ['composer-redesign · proposal', 'Composer · proposed', 'Attachment menu', 'Model menu', 'Thinking menu'].includes(n.name) || /^(\d+\. )/.test(n.name) || n.name.startsWith('Picker · ') || n.name === 'Menu position');
const removed = leftovers.map(n => n.name + ' ' + n.id);
for (const n of leftovers) n.remove();
await figma.loadFontAsync({ family: 'HarmonyOS Sans SC', style: 'Regular' });
await figma.loadFontAsync({ family: 'HarmonyOS Sans SC', style: 'Bold' });
const V = async (id) => figma.variables.getVariableByIdAsync(id);
const C = { canvas: await V('VariableID:9:80'), subtle: await V('VariableID:9:81'), raised: await V('VariableID:9:82'), text: await V('VariableID:9:83'), text2: await V('VariableID:9:84'), border: await V('VariableID:9:85'), borderStrong: await V('VariableID:9:86'), selected: await V('VariableID:835:1262'), text3: await V('VariableID:835:1263'), disabledText: await V('VariableID:835:1261') };
const S = { s4: await V('VariableID:9:31'), s8: await V('VariableID:9:32'), s16: await V('VariableID:9:34'), s24: await V('VariableID:9:36') };
const R = { small: await V('VariableID:9:41'), medium: await V('VariableID:9:42'), full: await V('VariableID:28:8') };
const TS = Object.fromEntries((await figma.getLocalTextStylesAsync()).map(s => [s.name, s]));
const ES = Object.fromEntries((await figma.getLocalEffectStylesAsync()).map(s => [s.name, s]));
const solid = (v) => figma.variables.setBoundVariableForPaint({ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }, 'color', v);
const radius = (n, v) => { for (const k of ['topLeftRadius', 'topRightRadius', 'bottomLeftRadius', 'bottomRightRadius']) n.setBoundVariable(k, v); };
const pad = (n, t, r, b, l) => { const set = (k, v) => { if (typeof v === 'number') n[k] = v; else n.setBoundVariable(k, v); }; set('paddingTop', t); set('paddingRight', r); set('paddingBottom', b); set('paddingLeft', l); };
const text = async (chars, style, color, name) => {
  const t = figma.createText();
  t.fontName = { family: 'HarmonyOS Sans SC', style: TS[style].fontName.style };
  t.characters = chars;
  await t.setTextStyleIdAsync(TS[style].id);
  t.fills = [solid(color)];
  if (name) t.name = name;
  return t;
};
const fill = (n) => { n.layoutSizingHorizontal = 'FILL'; };
const iconSet = await figma.getNodeByIdAsync('591:159');
const icon = (type) => iconSet.children.find(c => c.name === 'Type=' + type).createInstance();
const iconBtnSet = await figma.getNodeByIdAsync('9:145');
const rowSet = await figma.getNodeByIdAsync('321:3113');
const sectionTitle = await figma.getNodeByIdAsync('321:3114');
const sendIdle = (await figma.getNodeByIdAsync('9:127')).findOne(n => n.name === 'Send');
const sendReady = (await figma.getNodeByIdAsync('1197:5134')).findOne(n => n.name === 'Send');
const stopBtn = (await figma.getNodeByIdAsync('1197:5137')).findAll(n => n.type === 'INSTANCE' && n.parent && n.parent.name === 'Entry row').pop();
const attachSet = await figma.getNodeByIdAsync('1196:2836');

// build everything inside the root so a failure leaves nothing loose on the page
const root = figma.createAutoLayout('VERTICAL', { name: 'composer-redesign · proposal', itemSpacing: 16 });
pad(root, S.s24, S.s24, S.s24, S.s24);
root.fills = [solid(C.canvas)];
root.x = 7205; root.y = 3030;
root.resize(922, 10); root.counterAxisSizingMode = 'FIXED';
const pill = async (parent, label, { open = false, disabled = false } = {}) => {
  const p = figma.createAutoLayout('HORIZONTAL', { name: 'Picker · ' + label, itemSpacing: 4, counterAxisAlignItems: 'CENTER' });
  parent.appendChild(p);
  pad(p, S.s4, S.s8, S.s4, S.s8); radius(p, R.small);
  p.fills = open ? [solid(C.selected)] : [];
  p.appendChild(await text(label, 'Label', disabled ? C.disabledText : C.text, 'label'));
  const ch = icon('chevron-down'); ch.name = 'chevron'; p.appendChild(ch);
};
const composer = async (parent, { textValue = '', placeholder = 'Ask about this print or request a change…', scroll = false, attachments = [], model = 'Claude Opus 5.5', thinking = 'Thinking: Medium', open = null, streamingState = false, plusState = 'Default' }) => {
  const box = figma.createAutoLayout('VERTICAL', { name: 'Composer · proposed', itemSpacing: 4 });
  parent.appendChild(box); fill(box);
  pad(box, S.s8, S.s8, S.s8, S.s8); radius(box, R.medium);
  box.fills = [solid(C.canvas)];
  box.strokes = [solid(open || textValue || attachments.length ? C.borderStrong : C.border)]; box.strokeWeight = 1; box.strokeAlign = 'INSIDE';
  if (attachments.length) {
    const list = figma.createAutoLayout('VERTICAL', { name: 'Staged attachments', itemSpacing: 6 });
    box.appendChild(list); fill(list); list.fills = [];
    for (const a of attachments) {
      const inst = attachSet.children.find(c => c.name === 'Lifecycle=Staged, Preview=' + a.preview + ', Remove state=Normal').createInstance();
      list.appendChild(inst); fill(inst);
      for (const t of inst.findAll(n => n.type === 'TEXT')) {
        if (t.name === 'Filename') t.characters = a.name;
        if (t.name === 'Metadata') t.characters = a.meta;
        if (t.name === 'Kind label' && a.kind) t.characters = a.kind;
      }
    }
  }
  const input = figma.createAutoLayout('VERTICAL', { name: 'Input', itemSpacing: 0 });
  box.appendChild(input); fill(input); input.fills = []; pad(input, S.s4, S.s4, S.s4, S.s4);
  const t = await text(textValue || placeholder, 'Body Small', textValue ? C.text : C.text3, textValue ? 'Message' : 'Placeholder');
  input.appendChild(t); fill(t); t.textAutoResize = 'HEIGHT';
  if (scroll) {
    input.layoutSizingVertical = 'FIXED'; input.resize(input.width, 152); input.clipsContent = true;
    const thumb = figma.createRectangle(); thumb.name = 'Scroll thumb';
    input.appendChild(thumb); thumb.layoutPositioning = 'ABSOLUTE';
    thumb.resize(3, 56); thumb.x = input.width - 3; thumb.y = 88; radius(thumb, R.full); thumb.fills = [solid(C.text3)];
  }
  const bar = figma.createAutoLayout('HORIZONTAL', { name: 'Toolbar', itemSpacing: 8, counterAxisAlignItems: 'CENTER', primaryAxisAlignItems: 'SPACE_BETWEEN' });
  box.appendChild(bar); fill(bar); bar.fills = [];
  const left = figma.createAutoLayout('HORIZONTAL', { name: 'Choices', itemSpacing: 4, counterAxisAlignItems: 'CENTER' });
  bar.appendChild(left); left.fills = [];
  const plus = iconBtnSet.children.find(c => c.name === 'State=' + (streamingState ? 'Disabled' : plusState)).createInstance();
  left.appendChild(plus); plus.name = 'Attach';
  plus.findOne(n => n.type === 'INSTANCE').swapComponent(iconSet.children.find(c => c.name === 'Type=plus'));
  await pill(left, model, { open: open === 'model', disabled: streamingState });
  if (thinking) await pill(left, thinking, { open: open === 'thinking', disabled: streamingState });
  const send = (streamingState ? stopBtn : (textValue || attachments.length ? sendReady : sendIdle)).clone();
  bar.appendChild(send); send.name = streamingState ? 'Stop' : 'Send';
};
const menu = async (parent, items, name) => {
  const m = figma.createAutoLayout('VERTICAL', { name, itemSpacing: 2 });
  parent.appendChild(m);
  pad(m, S.s8, 0, S.s8, 0); radius(m, R.medium); m.fills = [solid(C.raised)];
  m.strokes = [solid(C.border)]; m.strokeWeight = 1; m.strokeAlign = 'INSIDE';
  await m.setEffectStyleIdAsync(ES['Elevation/Medium'].id);
  m.resize(240, 10); m.counterAxisSizingMode = 'FIXED';
  for (const it of items) {
    if (it.section) { const s = sectionTitle.createInstance(); m.appendChild(s); fill(s); s.findOne(n => n.type === 'TEXT').characters = it.section; continue; }
    const r = rowSet.children.find(c => c.name === 'State=' + (it.current ? 'Current' : 'Default')).createInstance();
    m.appendChild(r); fill(r);
    r.findOne(n => n.type === 'TEXT' && n.name === 'row-label').characters = it.label;
  }
};
const head = await text('Composer redesign · proposal', 'Section', C.text, 'Heading'); root.appendChild(head); fill(head); head.textAutoResize = 'HEIGHT';
const intro = await text('A proposal for the Agent message box, following the pattern of common AI chat apps: the box grows with the message, files are attached from a menu, and the model and thinking level are chosen per chat. It replaces the single-row Composer once approved; until then the shared Composer component is unchanged. Model names are examples.', 'Body Small', C.text2, 'Intro');
root.appendChild(intro); fill(intro); intro.textAutoResize = 'HEIGHT';
const grid = figma.createAutoLayout('HORIZONTAL', { name: 'States', itemSpacing: 16 });
root.appendChild(grid); fill(grid); grid.layoutWrap = 'WRAP'; grid.counterAxisSpacing = 16; grid.fills = [];
const cell = async (title, note) => {
  const c = figma.createAutoLayout('VERTICAL', { name: title, itemSpacing: 8 });
  grid.appendChild(c);
  pad(c, S.s16, S.s16, S.s16, S.s16); c.fills = [solid(C.subtle)]; radius(c, R.medium);
  c.resize(429, 10); c.counterAxisSizingMode = 'FIXED';
  const h = await text(title, 'Label Bold', C.text, 'Title'); c.appendChild(h); fill(h); h.textAutoResize = 'HEIGHT';
  const d = await text(note, 'Label', C.text2, 'Note'); c.appendChild(d); fill(d); d.textAutoResize = 'HEIGHT';
  return c;
};
const menuSlot = (c, indent) => { const w = figma.createAutoLayout('HORIZONTAL', { name: 'Menu position', itemSpacing: 0 }); c.appendChild(w); fill(w); w.fills = []; w.paddingLeft = indent; w.paddingTop = 8; return w; };

