  function Demo(p) {
    var v = React.useState(p.value || ''), m = React.useState('opus'), t = React.useState('medium');
    var levels = LEVELS[m[0]].map(function (l) { return { id: l.toLowerCase(), label: l }; });
    function pick(id) { m[1](id); if (!LEVELS[id].some(function (l) { return l.toLowerCase() === t[0]; })) t[1]('medium'); }
    return h('div', { style: { width: 397 } }, h(J.Composer, Object.assign({ models: MODELS, model: m[0], onModelChange: pick, thinkingLevels: levels, thinking: t[0], onThinkingChange: t[1] }, p, { value: v[0], onChange: v[1] })));
  }
  var col = { display: 'flex', flexDirection: 'column', gap: 12, paddingTop: 260 };
  render(h('div', { style: col }, h(Demo, null), h(Demo, { value: 'I need a slight adjustment on the left side.' }), h(Demo, { state: 'streaming' })),
