pickers[0].click(); await new Promise(r => setTimeout(r, 100));
menu = first.querySelector('.jp-composer-menu');
res.modelMenu = [...menu.children].map(c => c.textContent);
[...menu.querySelectorAll('.jp-menu-row')].find(b => b.textContent === 'GPT-5.4 mini').click();
await new Promise(r => setTimeout(r, 100));
res.afterMini = [...first.querySelectorAll('.jp-composer-picker')].map(p => p.textContent);
