const h12 = ta.getBoundingClientRect().height;
res.heights = [h0, h3, h12, ta.scrollHeight];
res.sendEnabled = !first.querySelector('.jp-btn-primary').disabled;
res.docHeight = document.documentElement.scrollHeight;
res

