const list = `__LIST__`;
const names = (await (await fetch('http://localhost:8766/')).text()).match(/href="([^"]+\.dc\.html\.html)"/g).map(s => s.slice(6, -1));
const out = {};
for (const n of names) {
  const html = await (await fetch('http://localhost:8766/' + n)).text();
  if (!html.includes('data-n="Composer box"')) continue;
  const fr = document.createElement('iframe');
  fr.style.cssText = 'position:fixed;left:0;top:0;width:1400px;height:1600px;visibility:hidden';
